package sites

import "phptools/internal/model"

// RewritePresets contains routing snippets for the server block generated by
// Render. PHP execution is provided by Render's existing FastCGI location.
// Every preset assumes its own domain and a deployment at the URL root.
func RewritePresets() []model.RewritePreset {
	return []model.RewritePreset{
		{
			ID: "laravel", Name: "Laravel", SuggestedEntry: "public",
			Description: "适用于独立域名下的常规 Laravel 路由；PHP 版本需满足项目要求。",
			SourceURL:   "https://laravel.com/docs/12.x/deployment#nginx",
			Rules: `# Laravel
location / {
    try_files $uri $uri/ /index.php?$query_string;
}`,
		},
		{
			ID: "thinkphp5", Name: "ThinkPHP 5.0 / 5.1", SuggestedEntry: "public",
			Description: "使用默认 index.php 和 s 路由参数，保留真实文件及目录；适用于常规模块路由。",
			SourceURL:   "https://doc.thinkphp.cn/@ln2qobnpdg/URLfangwen.html",
			Rules: `# ThinkPHP 5.0 / 5.1
location / {
    if (!-e $request_filename) {
        rewrite ^/(.*)$ /index.php?s=/$1 last;
    }
}`,
		},
		{
			ID: "thinkphp6-8", Name: "ThinkPHP 6 / 8", SuggestedEntry: "public",
			Description: "使用默认 index.php 和 s 路由参数，只绕过真实文件；多应用需由项目自行配置。",
			SourceURL:   "https://doc.thinkphp.cn/@94211x72gb/url_access.html",
			Rules: `# ThinkPHP 6 / 8
location / {
    if (!-f $request_filename) {
        rewrite ^/(.*)$ /index.php?s=/$1 last;
    }
}`,
		},
		{
			ID: "wordpress", Name: "WordPress（单站）",
			Description: "入口选含 wp-admin、wp-content 的安装目录，用于单站固定链接并禁止上传目录执行 PHP。不适用于多站网络；站点地址需包含实际域名和端口。",
			SourceURL:   "https://developer.wordpress.org/advanced-administration/server/web-server/nginx/",
			Rules: `# WordPress single site
location / {
    try_files $uri $uri/ /index.php?$args;
}

location ~* /(?:uploads|files)/.*\.php$ {
    deny all;
}`,
		},
		{
			ID: "yii2", Name: "Yii2", SuggestedEntry: "web",
			Description: "项目需启用 enablePrettyUrl，并设置 showScriptName=false。Advanced 前台选 frontend/web，后台选 backend/web，分别创建站点。",
			SourceURL:   "https://www.yiiframework.com/doc/guide/2.0/en/start-installation#recommended-nginx-configuration",
			Rules: `# Yii2
location / {
    try_files $uri $uri/ /index.php$is_args$args;
}

location ~ ^/assets/.*\.php$ {
    deny all;
}`,
		},
		{
			ID: "symfony", Name: "Symfony（美化 URL）", SuggestedEntry: "public",
			Description: "适用于 public/index.php 结构的美化 URL，仅提供路由规则；不包含完整官方服务器安全配置。旧 web/app.php 结构不适用。",
			SourceURL:   "https://symfony.com/doc/current/setup/web_server_configuration.html#nginx",
			Rules: `# Symfony pretty URLs
location / {
    try_files $uri /index.php$is_args$args;
}`,
		},
		{
			ID: "codeigniter4", Name: "CodeIgniter 4", SuggestedEntry: "public",
			Description: "项目需将 indexPage 设为空，baseURL 与站点地址一致，并使用默认 REQUEST_URI 路由模式。",
			SourceURL:   "https://codeigniter4.github.io/userguide/general/urls.html#nginx",
			Rules: `# CodeIgniter 4
location / {
    try_files $uri $uri/ /index.php$is_args$args;
}`,
		},
		{
			ID: "typecho", Name: "Typecho",
			Description: "入口选包含 index.php、admin 和 usr 的安装目录，并在后台启用地址重写；包含上传文件与备份目录保护。",
			SourceURL:   "https://docs.typecho.org/guide/operations/web-server",
			Rules: `# Typecho
location / {
    try_files $uri $uri/ /index.php$is_args$args;
}

location ~ ^/usr/(.+\.db$|backups/) {
    deny all;
}

location ~ ^/usr/uploads/.*\.php(/|$) {
    deny all;
}`,
		},
	}
}
